TIERS: tuple[str, ...] = ("flight-recorder", "governor", "orchestra")

# FR-M36-05: enabled tiers when nothing is configured — Flight Recorder only.
DEFAULT_ENABLED_TIERS: tuple[str, ...] = ("flight-recorder",)

